// Structural intake only. Imported claims never authenticate identities or completeness.
export const MAX_IMPORT_BYTES = 1024 * 1024;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
// `field` is generated by the parser. No input value is interpolated into a diagnostic.
const invalid = (field, message) => Object.assign(new Error(message), { field });
const text = (value, field, max = 1000) => {
  if (typeof value !== 'string' || !value.trim() || value.length > max) throw invalid(field, `${field} must be a nonempty string of at most ${max} characters.`);
  return value;
};
const id = (value, field) => {
  if (typeof value !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9:._-]{0,159}$/.test(value)) throw invalid(field, `${field} has an unsupported identifier.`);
  return value;
};
const parent = (value, field) => value === null ? null : id(value, field);
const list = (value, field, min = 0, max = 200) => {
  if (!Array.isArray(value) || value.length < min || value.length > max) throw invalid(field, `${field} must contain ${min}–${max} records.`);
  return value;
};
const pair = (value, field) => {
  if (!object(value)) throw invalid(field, 'Capability must be an action/resource pair.');
  return { action: text(value.action, field + '.action', 200), resource: text(value.resource, field + '.resource') };
};
const optional = (value, fallback, field) => value === undefined ? fallback : text(value, field, 2000);

export function parseInvestigation(contents) {
  if (typeof contents !== 'string' || contents.length > MAX_IMPORT_BYTES || new TextEncoder().encode(contents).length > MAX_IMPORT_BYTES) {
    throw invalid('$', 'Choose an investigation JSON file smaller than 1 MB.');
  }
  let envelope;
  try { envelope = JSON.parse(contents); } catch { throw invalid('$', 'The file is not valid JSON.'); }
  if (!object(envelope) || envelope.schemaVersion !== 1 || !object(envelope.chain)) {
    throw invalid(envelope?.schemaVersion === 1 ? 'chain' : 'schemaVersion', 'Expected a version 1 investigation export with a chain.');
  }
  const source = envelope.chain;
  const chainId = id(source.id, 'chain.id');
  if (chainId.startsWith('CH-')) throw invalid('chain.id', 'Imported IDs cannot replace built-in examples.');
  if (!object(source.principal)) throw invalid('chain.principal', 'Principal evidence is missing.');
  const grants = list(source.grants, 'chain.grants').map((grant, index) => {
    const path = `chain.grants[${index}]`;
    if (!object(grant) || typeof grant.canDelegate !== 'boolean') {
      throw invalid(path + '.canDelegate', 'Each grant must declare whether delegation is allowed.');
    }
    return { id: id(grant.id, path + '.id'), parentGrantId: parent(grant.parentGrantId, path + '.parentGrantId'),
      issuer: id(grant.issuer, path + '.issuer'), subject: id(grant.subject, path + '.subject'), principal: id(grant.principal, path + '.principal'),
      capabilities: list(grant.capabilities, path + '.capabilities', 0, 100).map((value, i) => pair(value, `${path}.capabilities[${i}]`)),
      validFrom: text(grant.validFrom, path + '.validFrom', 100), expiresAt: text(grant.expiresAt, path + '.expiresAt', 100), canDelegate: grant.canDelegate };
  });
  const events = list(source.events, 'chain.events', 1).map((event, index) => {
    const path = `chain.events[${index}]`;
    if (!object(event) || !object(event.action) || event.action.outcome !== 'completed') {
      throw invalid(path + '.action.outcome', 'Only completed actions can be investigated in this viewer.');
    }
    const normalized = { id: id(event.id, path + '.id'), parentEventId: parent(event.parentEventId, path + '.parentEventId'),
      actor: id(event.actor, path + '.actor'), authorityId: id(event.authorityId, path + '.authorityId'),
      label: optional(event.label, event.actor, path + '.label'), job: optional(event.job, 'Inspect the recorded action', path + '.job'),
      action: { ...pair(event.action, path + '.action'), at: text(event.action.at, path + '.action.at', 100), outcome: 'completed' } };
    if (object(event.evidence)) normalized.evidence = Object.fromEntries(['callId', 'tool', 'artifactSha256'].filter(key => event.evidence[key] !== undefined)
      .map(key => [key, text(event.evidence[key], path + '.evidence.' + key, 300)]));
    return normalized;
  });
  for (const [records, label] of [[grants, 'grant'], [events, 'event']]) {
    const seen = new Set();
    for (const [index, record] of records.entries()) {
      if (seen.has(record.id)) throw invalid(`chain.${label}s[${index}].id`, `Duplicate ${label} identifiers make this export ambiguous.`);
      seen.add(record.id);
    }
  }
  return { id: chainId, title: optional(source.title, 'Imported investigation', 'chain.title'),
    summary: optional(source.summary, 'Completed actions from a local file.', 'chain.summary'),
    principal: { id: id(source.principal.id, 'chain.principal.id'), name: optional(source.principal.name, source.principal.id, 'chain.principal.name'),
      role: optional(source.principal.role, 'Identity supplied by file', 'chain.principal.role') },
    rootGrantId: id(source.rootGrantId, 'chain.rootGrantId'), intent: optional(source.intent, 'Intent supplied in imported records', 'chain.intent'),
    completedAt: optional(source.completedAt, events.at(-1).action.at, 'chain.completedAt'), source: optional(source.source, 'Imported records', 'chain.source'),
    grants, events, imported: true };
}

export function mergeInvestigation(chains, imported) {
  if (!imported.imported || chains.some(chain => !chain.imported && chain.id === imported.id)) throw new Error('This import would replace a built-in example.');
  return [...chains.filter(chain => chain.id !== imported.id), imported];
}
